SELECT 'lease' AS CheckName, CASE WHEN OBJECT_DEFINITION(OBJECT_ID('dbo.app_ReclamarCorreo')) LIKE '%UPDLOCK%' AND OBJECT_DEFINITION(OBJECT_ID('dbo.app_ReclamarCorreo')) LIKE '%READPAST%' AND OBJECT_DEFINITION(OBJECT_ID('dbo.app_ReclamarCorreo')) LIKE '%ProcesandoHasta%' THEN 'PASS' ELSE 'FAIL' END AS Estado;
SELECT 'resolver_retry' AS CheckName, CASE WHEN OBJECT_DEFINITION(OBJECT_ID('dbo.app_ResolverCorreo')) LIKE '%Intentos+1%' AND OBJECT_DEFINITION(OBJECT_ID('dbo.app_ResolverCorreo')) LIKE '%ProximoIntento%' THEN 'PASS' ELSE 'FAIL' END AS Estado;
SELECT 'idempotencia_pedido' AS CheckName, CASE WHEN OBJECT_DEFINITION(OBJECT_ID('dbo.app_CrearPedido')) LIKE '%ClaveUnica%' AND OBJECT_DEFINITION(OBJECT_ID('dbo.app_CrearPedido')) LIKE '%NOT EXISTS%' THEN 'PASS' ELSE 'FAIL' END AS Estado;
SELECT 'idempotencia_pago' AS CheckName, CASE WHEN OBJECT_DEFINITION(OBJECT_ID('dbo.app_ActualizarPagoSeguro')) LIKE '%ClaveUnica%' AND OBJECT_DEFINITION(OBJECT_ID('dbo.app_ActualizarPagoSeguro')) LIKE '%NOT EXISTS%' THEN 'PASS' ELSE 'FAIL' END AS Estado;
SELECT 'cliente_exposure' AS CheckName, CASE WHEN NOT EXISTS(SELECT 1 FROM sys.procedures WHERE name IN ('app_DatosCorreoPedido')) THEN 'FAIL' ELSE 'PASS' END AS Estado;
